INSERT INTO Prospect (AgencyID, SK_RecordDateID, SK_UpdateDateID, BatchID, IsCustomer, LastName, FirstName, MiddleInitial, Gender, AddressLine1, AddressLine2, PostalCode, City, State, Country, Phone, Income, numberCars, numberChildren, MaritalStatus, Age, CreditRating, OwnOrRentFlag, Employer, numberCreditCards, NetWorth, MarketingNameplate) SELECT CAST(P.AgencyID AS TEXT) AS AgencyID, CAST((SELECT SK_DateID FROM DimDate WHERE DateValue = (SELECT BatchDate FROM Source.BatchDate)) AS INT) AS SK_RecordDateID, CAST((SELECT SK_DateID FROM DimDate WHERE DateValue = (SELECT BatchDate FROM Source.BatchDate)) AS INT) AS SK_UpdateDateID, CAST(1 AS DECIMAL(5)) AS BatchID, CAST(CASE WHEN EXISTS(SELECT 1 FROM DimCustomer AS C WHERE C.LastName = P.LastName AND C.FirstName = P.FirstName AND C.AddressLine1 = P.AddressLine1 AND C.AddressLine2 IS NOT DISTINCT FROM P.AddressLine2 AND C.PostalCode = P.PostalCode) THEN TRUE ELSE FALSE END AS BOOLEAN) AS IsCustomer, CAST(P.LastName AS TEXT) AS LastName, CAST(P.FirstName AS TEXT) AS FirstName, CAST(CASE WHEN P.MiddleInitial IS NULL OR TRIM(P.MiddleInitial) = '' THEN NULL ELSE SUBSTRING(TRIM(P.MiddleInitial), 1, 1) END AS TEXT) AS MiddleInitial, CAST(CASE WHEN UPPER(P.Gender) IN ('M', 'F') THEN UPPER(P.Gender) END AS TEXT) AS Gender, CAST(P.AddressLine1 AS TEXT) AS AddressLine1, CAST(P.AddressLine2 AS TEXT) AS AddressLine2, CAST(NULLIF(TRIM(P.PostalCode), '') AS TEXT) AS PostalCode, CAST(P.City AS TEXT) AS City, CAST(P.State AS TEXT) AS State, CAST(P.Country AS TEXT) AS Country, CAST(P.Phone AS TEXT) AS Phone, CAST(NULLIF(CAST(P.Income AS TEXT), '') AS DECIMAL(9)) AS Income, CAST(P.NumberCars AS DECIMAL(2)) AS numberCars, CAST(NULLIF(TRIM(CAST(P.NumberChildren AS TEXT)), '') AS DECIMAL(2)) AS numberChildren, CAST(NULLIF(P.MaritalStatus, '') AS TEXT) AS MaritalStatus, CAST(P.Age AS DECIMAL(3)) AS Age, TRY_CAST(P.CreditRating AS DECIMAL(4)) AS CreditRating, CAST(NULLIF(TRIM(P.OwnOrRentFlag), '') AS TEXT) AS OwnOrRentFlag, CAST(P.Employer AS TEXT) AS Employer, TRY_CAST(P.NumberCreditCards AS DECIMAL(2)) AS numberCreditCards, TRY_CAST(P.NetWorth AS DECIMAL(12)) AS NetWorth, CAST(NULL AS TEXT) AS MarketingNameplate FROM Source.Prospect AS P;
